/* Types main keeps in its .c files. */
typedef struct Anim {
     u32 file;
     s16 tick;
     s16 index;
     AnimFrame *frames;
     u32 *out;
} Anim;
typedef struct FxWork {
     PolFrame *frame;
     Anim anim;
     f32 pos[3];
     f32 vel[3];
     f32 scale;
     f32 grow;
     s32 alpha;
     s32 fade;
     u8 r;
     u8 g;
     u8 b;
     u8 kind;
     u8 unused40;
} FxWork;
typedef struct TextFrame {
     Frame frame;
     f32 x;
     f32 y;
     s16 w;
     s16 h;
     s16 xgap;
     s16 ygap;
     u32 base;
     u32 text;
     u8 flags;
     u8 r;
     u8 g;
     u8 b;
     u8 a;
} TextFrame;
typedef struct PadHist {
     u16 button;
     s8 x;
     s8 y;
} PadHist;
typedef struct DemoKey {
     u32 frames;
     PadHist pad;
} DemoKey;
typedef struct RideBox {
     u16 flags;
     f32 half[3];
     f32 pos[3];
     f32 rot[3];
     MtxF inv;
} RideBox;
typedef struct RideFrame {
     Frame f;
     s32 id;
     Frame *target;
     s16 count;
     f32 radius;
     RideBox *boxes;
     f32 reach;
     f32 center[3];
     MtxF inv;
} RideFrame;
typedef struct RideData {
     s16 count;
     f32 radius;
     u8 pad8[4];
     RideBox boxes[1];
} RideData;
typedef s32 (*TaskProc)(Obj *, s16, void *);
typedef struct MVtx {
     s16 ob[3];
     u16 flag;
     s16 tc[2];
     s8 cn[4];
} MVtx;
typedef struct ItexInit {
     s32 file;
     Gfx *dl;
     AnimFrame *frames;
     Color3 prim;
     Color3 env;
     s32 flags;
     f32 pos[3];
     f32 scale[3];
     Vec3f vel;
     Vec3f grow;
     s32 alpha;
     s32 fade;
     s32 life;
} ItexInit;
typedef struct PlStat {
     u8 pad0[3];
     s8 wpLv;
     u8 pad4[6];
} PlStat;
typedef struct SndSe {
     u8 prio;
     u8 flags;
     u8 pad2[2];
     u8 *data;
} SndSe;

